-- Run once in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.staff(id uuid primary key default gen_random_uuid(),name text not null unique check(length(trim(name)) between 1 and 40),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.tire_tags(id uuid primary key default gen_random_uuid(),tag_code text not null unique default ('TAG-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),brand text not null,width int not null check(width between 80 and 500),ratio int not null check(ratio between 20 and 100),rim int not null check(rim between 8 and 30),load_index text, speed_symbol text,season text not null check(season in ('夏','冬','オールシーズン')),free_qty int not null default 0 check(free_qty>=0),reserved_qty int not null default 0 check(reserved_qty>=0),sold_qty int not null default 0 check(sold_qty>=0),hold_qty int not null default 0 check(hold_qty>=0),version bigint not null default 1,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.stock_history(id bigint generated always as identity primary key,tag_id uuid not null references public.tire_tags(id),operation text not null,quantity int not null check(quantity>0),staff_id uuid references public.staff(id),staff_name text not null,note text,from_status text,to_status text,created_by uuid not null default auth.uid(),created_at timestamptz not null default now());
create index if not exists stock_history_tag_created on public.stock_history(tag_id,created_at desc);
alter table public.staff enable row level security;alter table public.tire_tags enable row level security;alter table public.stock_history enable row level security;
drop policy if exists staff_auth on public.staff;create policy staff_auth on public.staff for all to authenticated using(true) with check(true);
drop policy if exists tags_auth on public.tire_tags;create policy tags_auth on public.tire_tags for all to authenticated using(true) with check(true);
drop policy if exists history_auth on public.stock_history;create policy history_auth on public.stock_history for select to authenticated using(true);
create or replace function public.create_tag(p_brand text,p_width int,p_ratio int,p_rim int,p_load text,p_speed text,p_season text,p_initial int,p_staff uuid,p_note text default null) returns public.tire_tags language plpgsql security invoker as $$declare t public.tire_tags;s public.staff;begin select * into s from public.staff where id=p_staff and active; if not found then raise exception '担当者が無効です';end if;insert into public.tire_tags(brand,width,ratio,rim,load_index,speed_symbol,season,free_qty) values(trim(p_brand),p_width,p_ratio,p_rim,nullif(trim(p_load),''),nullif(upper(trim(p_speed)),''),p_season,p_initial) returning * into t;if p_initial>0 then insert into public.stock_history(tag_id,operation,quantity,staff_id,staff_name,note,to_status) values(t.id,'初期登録',p_initial,s.id,s.name,p_note,'free');end if;return t;end$$;
create or replace function public.change_stock(p_tag uuid,p_operation text,p_quantity int,p_staff uuid,p_note text,p_expected_version bigint) returns public.tire_tags language plpgsql security invoker as $$declare t public.tire_tags;s public.staff;f text;dest text;begin if p_quantity<=0 then raise exception '本数は1以上です';end if;select * into s from public.staff where id=p_staff and active;if not found then raise exception '担当者が無効です';end if;select * into t from public.tire_tags where id=p_tag and active for update;if not found then raise exception '電子荷票がありません';end if;if t.version<>p_expected_version then raise exception '在庫が他端末で更新されました。再読み込みしてください';end if;case p_operation when 'in' then t.free_qty:=t.free_qty+p_quantity;dest:='free';when 'reserve' then if t.free_qty<p_quantity then raise exception 'フリー在庫不足';end if;t.free_qty:=t.free_qty-p_quantity;t.reserved_qty:=t.reserved_qty+p_quantity;f:='free';dest:='reserved';when 'sold' then if t.reserved_qty<p_quantity then raise exception '売上予定在庫不足';end if;t.reserved_qty:=t.reserved_qty-p_quantity;t.sold_qty:=t.sold_qty+p_quantity;f:='reserved';dest:='sold';when 'out' then if t.sold_qty<p_quantity then raise exception '売上済み在庫不足';end if;t.sold_qty:=t.sold_qty-p_quantity;f:='sold';dest:='out';else raise exception '不正な処理区分';end case;update public.tire_tags set free_qty=t.free_qty,reserved_qty=t.reserved_qty,sold_qty=t.sold_qty,hold_qty=t.hold_qty,version=version+1,updated_at=now() where id=t.id returning * into t;insert into public.stock_history(tag_id,operation,quantity,staff_id,staff_name,note,from_status,to_status) values(t.id,p_operation,p_quantity,s.id,s.name,p_note,f,dest);return t;end$$;
create or replace function public.retire_tag(p_tag uuid,p_expected_version bigint) returns void language plpgsql security invoker as $$declare q int;begin select free_qty+reserved_qty+sold_qty+hold_qty into q from public.tire_tags where id=p_tag and version=p_expected_version for update;if not found then raise exception '他端末で更新済みです';end if;if q<>0 then raise exception '在庫が残っているため削除できません';end if;update public.tire_tags set active=false,version=version+1,updated_at=now() where id=p_tag;end$$;
revoke all on function public.create_tag(text,int,int,int,text,text,text,int,uuid,text) from public;grant execute on function public.create_tag(text,int,int,int,text,text,text,int,uuid,text) to authenticated;
revoke all on function public.change_stock(uuid,text,int,uuid,text,bigint) from public;grant execute on function public.change_stock(uuid,text,int,uuid,text,bigint) to authenticated;
revoke all on function public.retire_tag(uuid,bigint) from public;grant execute on function public.retire_tag(uuid,bigint) to authenticated;
insert into public.staff(name) values('管理者') on conflict do nothing;
